use mip_codex::{mps,heuristic::Repair,cover_greedy,solve::Result};use std::time::{Instant,Duration};
fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|v|v=="build-info"){println!("{}",serde_json::json!({"source_directory":env!("CARGO_MANIFEST_DIR"),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"library_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"library_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}let m=mps::read(&a[1]).unwrap();let repair=Repair::new(&m);let output=cover_greedy::candidate_portfolio(&m,&repair,Instant::now()+Duration::from_secs(2),true);let (mut point,mut stats)=output.unwrap_or_default();if std::env::var("MIP_PURE_COVER_EXCHANGE").is_ok_and(|v|v=="1"){if let Some(x)=point.as_ref(){if let Some((next,extra))=cover_greedy::exchange(&m,&repair,x,Instant::now()+Duration::from_secs(2),100_000_000){point=Some(next);stats.calls+=extra.calls;stats.work+=extra.work;stats.moves+=extra.moves;stats.improvements+=extra.improvements;}}}let r=Result{status:if point.is_some(){"feasible"}else{"unknown"}.into(),objective:point.as_ref().map(|x|m.objective(x)),values:point.map(|x|m.variables.iter().zip(x).map(|(v,x)|(v.name.clone(),x)).collect()),pure_cover_greedy:Some(stats),..Result::default()};println!("{}",serde_json::to_string(&r).unwrap());}
